   249	struct Lookup
   250	{
   251	  inline const T* get_value (hb_codepoint_t glyph_id, unsigned int num_glyphs) const
   252	  {
   253	    switch (u.format) {
   254	    case 0: return u.format0.get_value (glyph_id, num_glyphs);
   255	    case 2: return u.format2.get_value (glyph_id);
   256	    case 4: return u.format4.get_value (glyph_id);
   257	    case 6: return u.format6.get_value (glyph_id);
   258	    case 8: return u.format8.get_value (glyph_id);
   259	    default:return nullptr;
   260	    }
   261	  }
   262	
   263	  inline const T& get_value_or_null (hb_codepoint_t glyph_id, unsigned int num_glyphs) const
   264	  {
   265	    const T *v = get_value (glyph_id, num_glyphs);
   266	    return v ? *v : Null(T);
   267	  }
