   269	  inline bool sanitize (hb_sanitize_context_t *c) const
   270	  {
   271	    TRACE_SANITIZE (this);
   272	    if (!u.format.sanitize (c)) return_trace (false);
   273	    switch (u.format) {
   274	    case 0: return_trace (u.format0.sanitize (c));
   275	    case 2: return_trace (u.format2.sanitize (c));
   276	    case 4: return_trace (u.format4.sanitize (c));
   277	    case 6: return_trace (u.format6.sanitize (c));
   278	    case 8: return_trace (u.format8.sanitize (c));
